const fs = require('fs-extra')
const path = require('path')

main().catch(swallow)

// set-up local testing env
async function main() {
  fs.ensureDir(path.join(__dirname, '../build'))
  const depsPath = path.join(__dirname, '../deps')
  const destPath = path.join(__dirname, '../node_modules')
  if (await isDirectory(depsPath)) {
    const depsFiles = []
    const rawDepsFiles = await fs.readdir(depsPath)
    for (const name of rawDepsFiles) {
      if (name.startsWith('@')) {
        const nsFiles = await fs.readdir(path.join(depsPath, name))
        for (const nsName of nsFiles) {
          depsFiles.push(path.join(name, nsName))
        }
      } else {
        depsFiles.push(name)
      }
    }
    await Promise.all(
      depsFiles.map(async name => {
        const destPkgPath = path.join(destPath, name)
        await fs.remove(destPkgPath).catch(swallow)
        await fs.ensureDir(destPkgPath).catch(swallow)
        await fs.copy(path.join(depsPath, name), destPkgPath).catch(swallow)
      })
    )
  }
}

async function isDirectory(dirPath) {
  const dirStat = await fs.stat(dirPath).catch(swallow)
  return Boolean(dirStat && dirStat.isDirectory())
}

function swallow() {
  return null
}

function encodeBase64(value: string): string {
  const scope = globalThis as any

  if (typeof scope.btoa === 'function') {
    return scope.btoa(unescape(encodeURIComponent(value)))
  }

  if (scope.Buffer) {
    return scope.Buffer.from(value, 'utf8').toString('base64')
  }

  throw new Error('Base64 encoding is not available in the current runtime.')
}

export function createBasicAuthorizationHeader(
  username: string,
  password: string
): string {
  return `Basic ${encodeBase64(`${username}:${password}`)}`
}

import { AppConfig } from '@/app-config'
import { isFirefox, isOpera, isSafari } from './saladict'

export async function checkBackgroundPermission(
  config: AppConfig
): Promise<void> {
  // Firefox, Opera and Safari does not support 'background' permission.
  if (isFirefox || isOpera || isSafari) return

  const backgroundPermissions: browser.permissions.AnyPermissions = {
    permissions: ['background']
  }
  const hasBackground = await browser.permissions.contains(
    backgroundPermissions
  )
  if (config.runInBg) {
    if (!hasBackground) {
      await browser.permissions.request(
        backgroundPermissions as browser.permissions.Permissions
      )
    }
  } else {
    if (hasBackground) {
      try {
        await browser.permissions.remove(
          backgroundPermissions as browser.permissions.Permissions
        )
      } catch (e) {
        // failed silently on remove
        console.error(e)
      }
    }
  }
}

